def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            todo = [(r, c)]
            seen.add((r, c))
            cells = []
            while todo:
                a, b = todo.pop()
                cells.append((a, b))
                for da, db in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    aa, bb = a + da, b + db
                    if (0 <= aa < h and 0 <= bb < w and
                            grid[aa][bb] == color and (aa, bb) not in seen):
                        seen.add((aa, bb))
                        todo.append((aa, bb))
            out.append((color, cells))
    return out


def _shape8(cells):
    forms = []
    for mode in range(8):
        pts = []
        for r, c in cells:
            variants = ((r, c), (r, -c), (-r, c), (-r, -c),
                        (c, r), (c, -r), (-c, r), (-c, -r))
            pts.append(variants[mode])
        r0 = min(r for r, c in pts)
        c0 = min(c for r, c in pts)
        forms.append(tuple(sorted((r-r0, c-c0) for r, c in pts)))
    return min(forms)


def transform(grid):
    g = [row[:] for row in grid]
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    comps = _components(g, bg)

    # The long orthogonal marker determines the replacement color.
    markers = []
    for color, cells in comps:
        rows = Counter(r for r, c in cells)
        cols = Counter(c for r, c in cells)
        if len(cells) >= 7 and max(rows.values()) >= 4 and max(cols.values()) >= 4:
            markers.append((len(cells), color))
    if not markers:
        return g
    paint = max(markers)[1]

    # Find the largest repeated silhouette family containing a background-
    # colored candidate and a differently colored reference object.
    families = {}
    for color, cells in comps:
        families.setdefault(_shape8(cells), []).append((color, cells))
    choices = []
    for copies in families.values():
        if len(copies) < 2:
            continue
        colors = {color for color, _ in copies}
        if len(colors) < 2:
            continue
        for color, cells in copies:
            # Select the outlier member when a repeated motif differs in color.
            if color != Counter(c for c, _ in copies).most_common(1)[0][0]:
                choices.append((len(cells), color, cells))
    if choices:
        _, _, cells = max(choices, key=lambda item: item[0])
        for r, c in cells:
            g[r][c] = paint
    return g


