    # The guide's horizontal arm points toward the nearby 3x3 hollow-color
    # motif. Recolor that motif to the color of the repeated filled 3x3 motif.
    # Select the color by the majority color among connected 3x3 patches.
    motifs = []
    for color, groups in comps.items():
