def _rect_shape(grid, cells):
    r0=min(r for r,c in cells); r1=max(r for r,c in cells)
    c0=min(c for r,c in cells); c1=max(c for r,c in cells)
    if len(cells)!=(r1-r0+1)*(c1-c0+1): return None
    return (r1-r0+1,c1-c0+1)


def transform(grid):
    out=[row[:] for row in grid]
    bg=Counter(v for row in out for v in row).most_common(1)[0][0]
    comps=_components(out,bg)
    # Identify salient line-shaped key components and their color.
    keys=[]
    for color,cells in comps:
        rcounts=Counter(r for r,c in cells); ccounts=Counter(c for r,c in cells)
        if len(cells)>=3 and (max(rcounts.values())==len(cells) or max(ccounts.values())==len(cells)):
            keys.append((len(cells),color,cells))
    if not keys: return out
    _, keycolor,keycells=max(keys)

    # Look for a rectangular block matching one of the 3xN/ Nx3 glyphs; if
    # the same rectangle occurs in a second palette color, recolor the keyed copy.
    rects=[]
    for color,cells in comps:
        shape=_rect_shape(out,cells)
        if shape and min(shape)>=2:
            rects.append((color,cells,shape))
    grouped={}
    for color,cells,shape in rects: grouped.setdefault(shape,[]).append((color,cells))
    for shape,copies in grouped.items():
        colors={color for color,_ in copies}
        if len(colors)<2: continue
        # The key color guides the destination; infer the dominant motif color.
        ref=Counter(color for color,_ in copies).most_common(1)[0][0]
        for color,cells in copies:
            if color!=ref:
                for r,c in cells: out[r][c]=keycolor
                return out

    # A foreground line key can point to a small line-shaped target at its
    # open endpoint. In demos the matched target is a component of the same
    # line color family, at an isolated matching-color occurrence.
    return out


if __name__ == '__main__':
    import json,sys
    print(json.dumps(transform(json.load(sys.stdin))))
