def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr, nc = rr+dr, cc+dc
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color
                            and (nr,nc) not in seen):
                        seen.add((nr,nc)); q.append((nr,nc))
            result.append((color,cells))
    return result


def _shape(cells):
    r0=min(r for r,c in cells); c0=min(c for r,c in cells)
    return tuple(sorted((r-r0,c-c0) for r,c in cells))


def transform(grid):
    out=[row[:] for row in grid]
    bg=Counter(v for row in out for v in row).most_common(1)[0][0]
    comps=_components(out,bg)
    by_shape={}
    for color,cells in comps:
        by_shape.setdefault(_shape(cells),[]).append((color,cells))
    # Key color is the most prominent line component's color.
    line_keys=[]
    for color,cells in comps:
        rs=Counter(r for r,c in cells); cs=Counter(c for r,c in cells)
        if len(cells)>=3 and (max(rs.values())==len(cells) or max(cs.values())==len(cells)):
            line_keys.append((len(cells),color,cells))
    if not line_keys:return out
    keycolor=max(line_keys)[1]
    # A repeated exact silhouette with different color is the recoloring target.
    for copies in by_shape.values():
        counts=Counter(color for color,_ in copies)
        if len(copies)>1 and len(counts)>1:
            reference=counts.most_common(1)[0][0]
            for color,cells in copies:
                if color!=reference:
                    for r,c in cells:out[r][c]=keycolor
                    return out
    return out


